// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // Wide admissible domain: no setup changes the pause flag, and neither
        // the fuzzed amount nor the fuzzed actor address can. In the reference
        // contract, a contract that has never been paused must report
        // paused() == false for every input; the mutant negates the flag and
        // reports true, breaking this rule for (all, hence some) inputs.
        vm.assume(amount < type(uint256).max);
        vm.assume(actor != address(0));
        assertTrue(c.paused() == false);
    }
}
